// CONFIG: edit this array to add/remove watched provider pages.
// Prefer stable pricing/terms URLs over marketing pages.
var providers = [
  { name: 'Google AI Studio',  url: 'https://ai.google.dev/pricing',                                   note: 'Gemini API free tier limits' },
  { name: 'Groq',             url: 'https://groq.com/pricing',                                        note: 'Free inference rate limits' },
  { name: 'Mistral',          url: 'https://mistral.ai/pricing',                                     note: 'La Plateforme free/experiment plan' },
  { name: 'NVIDIA NIM',       url: 'https://build.nvidia.com/terms',                                 note: 'Free tier terms of use' },
  { name: 'Cloudflare Workers', url: 'https://developers.cloudflare.com/workers/platform/pricing/',  note: 'Workers free tier' },
  { name: 'Supabase',         url: 'https://supabase.com/pricing',                                   note: 'Free plan limits + pause policy' },
  { name: 'Neon',             url: 'https://neon.com/pricing',                                       note: 'Free Postgres plan' },
  { name: 'GitHub Actions',   url: 'https://docs.github.com/en/billing/managing-billing-for-github-actions', note: 'Free minutes' },
  { name: 'n8n',              url: 'https://n8n.io/pricing/',                                        note: 'Self-host vs cloud terms' },
  { name: 'OpenRouter',       url: 'https://openrouter.ai/docs',                                     note: 'Free model availability' },
  { name: 'Cohere',           url: 'https://cohere.com/pricing',                                     note: 'Trial key terms' },
  { name: 'Brevo',            url: 'https://www.brevo.com/pricing/',                                 note: 'Free email tier' }
];
return providers.map(function (p) { return { json: p }; });

// Hash & Compare — runs once for all items.
// Compares each fetched page against the stored hash in workflow static data.
// Outputs ONLY actionable items (changed pages + fetch errors). Zero items = no-op.

function cyrb53(str, seed) {
  seed = seed || 0;
  var h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (var i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}

function hashPage(str) {
  try {
    var crypto = require('crypto'); // needs NODE_FUNCTION_ALLOW_BUILTIN=crypto
    return { hash: crypto.createHash('sha256').update(str, 'utf8').digest('hex'), algo: 'sha256' };
  } catch (e) {
    return { hash: 'cyrb53:' + cyrb53(str), algo: 'cyrb53-fallback' };
  }
}

// Static data persists in n8n's database across executions.
var staticData = $getWorkflowStaticData('global');
if (!staticData.tosHashes || typeof staticData.tosHashes !== 'object') {
  staticData.tosHashes = {};
}

var urlItems = $('Provider URL List').all().map(function (it) { return it.json; });
var fetched = $input.all();
var checkedAt = new Date().toISOString();
var actionable = [];

for (var idx = 0; idx < urlItems.length; idx++) {
  var meta = urlItems[idx];
  var res = fetched[idx] ? fetched[idx].json : {};

  if (res && res.error) {
    actionable.push({ json: {
      name: meta.name, url: meta.url, status: 'fetch_error',
      error: String((res.error && res.error.message) || res.error),
      checkedAt: checkedAt
    }});
    continue;
  }

  var raw = (res && typeof res.data === 'string') ? res.data : JSON.stringify(res || {});
  var r = hashPage(raw);
  var prev = staticData.tosHashes[meta.url] || null;

  if (prev === null) {
    staticData.tosHashes[meta.url] = r.hash; // first run: record baseline silently
    continue;
  }
  if (prev !== r.hash) {
    staticData.tosHashes[meta.url] = r.hash;
    actionable.push({ json: {
      name: meta.name, url: meta.url, status: 'changed',
      previousHash: prev, hash: r.hash, algo: r.algo, checkedAt: checkedAt
    }});
  }
}

return actionable;
